<template><div><svg class="line-chart" viewBox="0 0 660 210" role="img" :aria-label="`消息趋势，共 ${sum} 条样本消息`"><title>消息趋势（样本）：{{ sum }} 条</title><g v-for="i in 4" :key="i"><line class="chart-grid" x1="38" x2="646" :y1="20+(i-1)*50" :y2="20+(i-1)*50"/><text class="chart-label" x="29" :y="23+(i-1)*50" text-anchor="end">{{ Math.round(max*(4-i)/3) }}</text></g><path v-if="points.length" class="chart-area" :d="area"/><path v-if="points.length" class="chart-line" :d="line"/><circle v-for="(point,i) in coords" :key="i" class="chart-dot" :cx="point.x" :cy="point.y" :r="points.length<10?3:1.5"><title>{{ points[i].date }}：{{ points[i].value }} 条</title></circle><template v-for="(point,i) in coords" :key="'label'+i"><text v-if="i===0||i===coords.length-1||i%Math.ceil(coords.length/6)===0" class="chart-label" :x="point.x" y="198" text-anchor="middle">{{ points[i].label }}</text></template></svg><details class="chart-data"><summary>查看每日数据</summary><div class="native-chart-table"><table><thead><tr><th>日期</th><th>样本消息数</th></tr></thead><tbody><tr v-for="point in points" :key="point.date"><td>{{ point.date }}</td><td>{{ point.value }}</td></tr></tbody></table></div></details></div></template>
<script>
export default {name:'TrendChart',props:{points:{type:Array,default:()=>[]}},computed:{sum(){return this.points.reduce((s,p)=>s+p.value,0)},max(){return Math.max(3,...this.points.map(p=>p.value))},coords(){return this.points.map((p,i)=>({x:38+(i/(this.points.length-1||1))*608,y:170-p.value/this.max*150}))},line(){return this.coords.map((p,i)=>`${i?'L':'M'} ${p.x} ${p.y}`).join(' ')},area(){return this.line+` L 646 170 L 38 170 Z`}}}
</script>
